import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · Lesson 28 No parking","description":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 28 No parking","description":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 动名词与动词搭配，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 27 A wet night","link":"/life/english/new-concept/book-2/unit-02/lesson-027"},"next":{"text":"第二册：实践与进步 · Lesson 29 Taxi!","link":"/life/english/new-concept/book-2/unit-02/lesson-029"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 27 A wet night","link":"/life/english/new-concept/book-2/unit-02/lesson-027"},"next":{"text":"第二册：实践与进步 · Lesson 29 Taxi!","link":"/life/english/new-concept/book-2/unit-02/lesson-029"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-02/lesson-028.md","filePath":"life/english/new-concept/book-2/unit-02/lesson-028.md"}'),i={name:"life/english/new-concept/book-2/unit-02/lesson-028.md"};function r(l,e,s,c,h,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-lesson-28-no-parking" tabindex="-1">第二册：实践与进步 · Lesson 28 No parking <a class="header-anchor" href="#第二册-实践与进步-·-lesson-28-no-parking" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 28 No parking&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>私人入口前经常有人停车，简单告示需要传达明确限制；练习名词短语告示与完整句的对应。本课的语言观察是：No parking 是 no 加动名词名词化的告示，不是完整陈述句。改写时可用 You must not park here，禁止意义比请求强。完成学习后，请为一个入口写两句告示，再加一句解释通行需求。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>gate</td><td>/ɡeɪt/</td><td>n.</td><td>大门</td><td>a garden gate</td></tr><tr><td>permit</td><td>/pəˈmɪt/</td><td>v.</td><td>允许</td><td>permit entry</td></tr><tr><td>traffic</td><td>/ˈtræfɪk/</td><td>n.</td><td>交通</td><td>heavy traffic</td></tr><tr><td>entrance</td><td>/ˈentrəns/</td><td>n.</td><td>入口</td><td>the main entrance</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>keep clear — 保持畅通，常见于入口提示</li><li>prevent somebody from doing — 阻止某人做某事</li></ul><h2 id="语法讲解-动名词与动词搭配" tabindex="-1">语法讲解：动名词与动词搭配 <a class="header-anchor" href="#语法讲解-动名词与动词搭配" aria-label="Permalink to &quot;语法讲解：动名词与动词搭配&quot;">​</a></h2><p>动词的 -ing 形式可像名词一样作主语或宾语，常出现在 enjoy、avoid、finish 等动词之后，以及介词之后。它仍能带自己的宾语或状语。另一些动词通常接 to 不定式，不能按中文意思随意互换；stop、remember、try 等词接两种形式时意思还可能改变。遇到 to 先判断它是不定式标记还是介词，再决定后面使用原形还是 -ing。本课应用：No parking 是 no 加动名词名词化的告示，不是完整陈述句。改写时可用 You must not park here，禁止意义比请求强。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Parking beside this gate blocks the entrance.</p></blockquote><p>在这扇门旁停车会堵住入口。</p><p>Parking beside this gate 是动名词短语作主语，整体视为单数，谓语用 blocks。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Parking ... block 缺少第三人称单数词尾；一个动名词短语通常按单数看待。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 parking 与 blocks，重读 blocks 说明后果；keep clear 的两个词都清楚发音。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Parking beside this gate blocks the entrance. Delivery vans need room to turn. Visitors can use the public car park nearby.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>为一个入口写两句告示，再加一句解释通行需求。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：Parking beside this gate 是动名词短语作主语，整体视为单数，谓语用 blocks。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：Parking ... block 缺少第三人称单数词尾；一个动名词短语通常按单数看待。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 block：Parking here ___ the entrance.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> blocks</p><p><strong>解析：</strong> 动名词短语主语按单数处理。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>访客可以在哪里停车？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> In the nearby public car park.</p><p><strong>解析：</strong> 示范提供替代地点，没有禁止所有地方停车。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 must not 改写 No parking here。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> You must not park here.</p><p><strong>解析：</strong> must not 明确表示禁止。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：动名词与动词搭配。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-02/lesson-027">上一课</a> · <a href="/life/english/new-concept/book-2/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-02/lesson-029">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=a(i,[["render",r]]);export{u as __pageData,k as default};
